let checklistHistoryDay='',checklistHistoryGeneration=0;
function mountChecklistHistory(){if(location.hash!=='#checklist')return;const panel=document.querySelector('.task-today-panel');if(!panel||document.querySelector('#checklist-history-controls'))return;const today=taskDay();if(!checklistHistoryDay)checklistHistoryDay=today;const controls=document.createElement('div');controls.id='checklist-history-controls';controls.className='checklist-history-controls';controls.innerHTML=`<label>업무 날짜 <input class="field" type="date" id="checklist-history-date" value="${checklistHistoryDay}"></label><div class="checklist-date-buttons"><button type="button" class="task-edit-save" data-checklist-shift="-1" aria-label="선택한 날짜의 전날">어제</button><button type="button" class="task-edit-save" id="checklist-history-today">오늘</button><button type="button" class="task-edit-save" data-checklist-shift="1" aria-label="선택한 날짜의 다음날">내일</button></div>`;panel.before(controls);const past=document.createElement('section');past.id='checklist-history-panel';past.className='panel';panel.after(past);controls.querySelector('input').onchange=e=>{checklistHistoryDay=e.target.value||today;paintChecklistHistory();};controls.querySelectorAll('[data-checklist-shift]').forEach(b=>b.onclick=()=>{const date=new Date(checklistHistoryDay+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+Number(b.dataset.checklistShift));checklistHistoryDay=date.toISOString().slice(0,10);controls.querySelector('input').value=checklistHistoryDay;paintChecklistHistory();});controls.querySelector('#checklist-history-today').onclick=()=>{checklistHistoryDay=today;controls.querySelector('input').value=today;paintChecklistHistory();};paintChecklistHistory();}
async function paintChecklistHistory(){const panel=document.querySelector('.task-today-panel'),past=document.querySelector('#checklist-history-panel');if(!panel||!past)return;const day=checklistHistoryDay,today=taskDay(),generation=++checklistHistoryGeneration;panel.hidden=day!==today;past.hidden=day===today;if(day===today)return;past.innerHTML='<p>기록을 불러오는 중…</p>';try{const d=await api('/api/task-history?day='+encodeURIComponent(day));if(generation!==checklistHistoryGeneration||!past.isConnected)return;past.innerHTML=`<h2>${esc(day)} ${day>today?'예정 업무':'업무 기록'}</h2><p class="muted">${day>today?'현재 반복 요일 기준의 예정 목록입니다. 완료 체크는 해당 날짜가 되면 할 수 있습니다.':d.saved?'저장된 날짜별 업무 기록입니다.':'저장된 업무 목록이 없어 현재 반복 요일 기준 목록을 보여드립니다. 완료 표시는 해당 날짜의 기존 XP 기록과 연결합니다.'} ${day<today?'지난 날짜 수정은 XP에 영향을 주지 않습니다.':''}</p><div>${d.tasks.map((t,i)=>`<label class="history-task-row"><input type="checkbox" data-history-task="${i}" ${day>today?'disabled':''} ${t.done?'checked':''}><span>${esc(t.title)}</span><small>${day>today?'예정':t.done?'완료':'미완료'}</small></label>`).join('')||'<p class="muted">이 날짜에 표시할 업무가 없습니다.</p>'}</div><p role="status" id="checklist-history-status" class="muted"></p>`;past.querySelectorAll('[data-history-task]').forEach(input=>input.onchange=async()=>{input.disabled=true;try{await api('/api/task-history',{day,title:d.tasks[Number(input.dataset.historyTask)].title,done:input.checked});input.closest('label').querySelector('small').textContent=input.checked?'완료':'미완료';past.querySelector('[role=status]').textContent='날짜별 기록을 저장했습니다.';}catch(error){input.checked=!input.checked;past.querySelector('[role=status]').textContent=error.message;}finally{input.disabled=false;}});}catch(error){if(generation===checklistHistoryGeneration)past.textContent=error.message;}}
setInterval(mountChecklistHistory,500);

